import json,glob,collections
def cat(p):
    if not p: return 'other'
    if '/.claude/reference/' in p or p.startswith('.claude/reference'): return 'reference'
    if '/spec/' in p or p.startswith('spec/'): return 'spec'
    if '/src/' in p or p.startswith('src/'): return 'src'
    return 'other'
tot=collections.Counter(); carried=collections.Counter(); calls=collections.Counter()
sessions=0; firsts=[]
for f in glob.glob('*.jsonl'):
    ev=[]
    for line in open(f):
        try: ev.append(json.loads(line))
        except: pass
    turns=[i for i,d in enumerate(ev) if d.get('type')=='assistant' and (d.get('message') or {}).get('usage')]
    if not turns: continue
    u=ev[turns[0]]['message']['usage']
    first=u.get('input_tokens',0)+u.get('cache_creation_input_tokens',0)+u.get('cache_read_input_tokens',0)
    if not (50000<first<60000): continue
    sessions+=1
    ids={}
    for i,d in enumerate(ev):
        m=d.get('message') or {}
        c=m.get('content') if isinstance(m,dict) else None
        if not isinstance(c,list): continue
        for b in c:
            if b.get('type')=='tool_use':
                inp=b.get('input',{})
                if b.get('name')=='Read': ids[b['id']]=('Read',cat(inp.get('file_path')))
                elif b.get('name')=='Bash':
                    cmd=inp.get('command','')
                    k='bash-ref' if '.claude/reference' in cmd else 'bash-spec' if 'spec/' in cmd else 'bash-other'
                    ids[b['id']]=('Bash',k)
                else: ids[b['id']]=(b.get('name'),'-')
            if b.get('type')=='tool_result' and b.get('tool_use_id') in ids:
                cc=b.get('content'); 
                s=len(cc) if isinstance(cc,str) else sum(len(x.get('text','')) for x in cc or [] if isinstance(x,dict))
                key=ids[b['tool_use_id']]
                tok=s/3.6
                tot[key]+=tok; calls[key]+=1
                later=sum(1 for t in turns if t>i)
                carried[key]+=tok*later
print("sessions",sessions)
allc=sum(carried.values())
for k,v in sorted(tot.items(),key=lambda x:-x[1])[:14]:
    print(f"{str(k):32} calls={calls[k]:5} tokens={v/1e3:8.0f}k per-session={v/sessions/1e3:6.1f}k carried={carried[k]/1e6:7.1f}M")
EOF

